    /// invocations through `MutationEngine::dispatch_method_call`
    /// (Requirement 5 / VAL-DISPATCH-001).
    pub fn with_engine(
        plugin_id: String,
        route: PluginRoute,
        engine: Option<Arc<MutationEngine>>,
    ) -> Self {
        let mut iface = Self::with_shm_state_dir(plugin_id, route, DEFAULT_SHM_STATE_DIR);
        iface.engine = engine;
        iface
    }

