    ///
    /// In production, use [`new`](Self::new) which targets `/dev/shm/opdbus/state`.
    /// Tests should supply a temporary directory.
    pub fn with_shm_state_dir(
        plugin_id: String,
        route: PluginRoute,
        shm_state_dir: impl AsRef<Path>,
